CREATE DATABASE IF NOT EXISTS checksum_demo;
USE checksum_demo;
CREATE TABLE IF NOT EXISTS students (id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, course VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS products (id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, price DECIMAL(10,2) NOT NULL);
CREATE TABLE IF NOT EXISTS table_checksums (table_name VARCHAR(100) PRIMARY KEY, checksum_value CHAR(64) NOT NULL, row_count BIGINT NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS checksum_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, table_name VARCHAR(100) NOT NULL, stored_checksum CHAR(64), calculated_checksum CHAR(64), stored_rows BIGINT, calculated_rows BIGINT, status VARCHAR(20) NOT NULL, checked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
